function dp_expandContent(d) {
  const hasCuratedInfo = !!(d.description || d.citation || d.link);

  const curatedBlock = hasCuratedInfo
    ? html`&lt;div class="dp-desc"&gt;
        ${d.description ? html`&lt;p class="dp-fact"&gt;${d.description}&lt;/p&gt;` : ""}
        ${d.citation ? html`&lt;p class="dp-fact dp-citation"&gt;${d.citation}&lt;/p&gt;` : ""}
        ${d.link ? html`&lt;p class="dp-fact"&gt;&lt;a href=${d.link} target="_blank" rel="noopener noreferrer"&gt;${d.link}&lt;/a&gt;&lt;/p&gt;` : ""}
      &lt;/div&gt;`
    : html`&lt;div class="dp-note"&gt;No study description, citation, or link on file yet.&lt;/div&gt;`;

  const liveNote = d.isLiveImport
    ? html`&lt;div class="dp-note live"&gt;&lt;strong&gt;Live import.&lt;/strong&gt; Grows automatically as new
        ManyNumbers site submissions arrive — currently ${d.n} participants across ${d.countries.length} sites.&lt;/div&gt;`
    : "";

  const trialFact = d.hasTrialData
    ? html`&lt;p class="dp-fact"&gt;&lt;b&gt;${d.nTrials?.toLocaleString()}&lt;/b&gt; trials logged${d.numbersTested ? html` · numbers tested &lt;b&gt;${d.numbersTested}&lt;/b&gt;` : ""}&lt;/p&gt;`
    : html`&lt;p class="dp-fact"&gt;no trial-by-trial data on file&lt;/p&gt;`;

  return html`&lt;div class="dp-expand"&gt;
    &lt;div class="dp-badge-row"&gt;${[
    ...d.methods,
    ...(d.nWithAms &gt; 0 ? ["Dot Comparison"] : []),
    ...(d.nWithVm &gt; 0 ? ["Visual Memory"] : []),
  ].map(m =&gt; html`&lt;span class="dp-badge"&gt;${m}&lt;/span&gt;`)}&lt;/div&gt;
    ${curatedBlock}
    ${liveNote}
    &lt;p class="dp-fact"&gt;&lt;b&gt;${d.n}&lt;/b&gt; participants${d.ageMin != null ? html` · ages &lt;b&gt;${d.ageMin}–${d.ageMax} mo&lt;/b&gt;` : ""}&lt;/p&gt;
    &lt;p class="dp-fact"&gt;Languages: ${d.languages.length ? d.languages.join(", ") : "—"}&lt;/p&gt;
    &lt;p class="dp-fact"&gt;Countries: ${d.countries.length ? d.countries.join(", ") : "—"}&lt;/p&gt;
    ${trialFact}
    ${d.nWithHc &gt; 0 ? html`&lt;p class="dp-fact"&gt;Highest Count on file for &lt;b&gt;${d.nWithHc}&lt;/b&gt; of ${d.n} participants&lt;/p&gt;` : ""}
  &lt;/div&gt;`;
}

// wraps any Inputs.select(..., {multiple: true}) view with "All"/"None"
// buttons that set its value and fire the same input event Observable's
// reactivity expects, so viewof cells built from this stay wired up exactly
// like the Inputs.select they wrap
function withAllNoneButtons(view, allValues) {
  const allBtn = html`&lt;button type="button" class="filter-allnone-btn"&gt;All&lt;/button&gt;`;
  const noneBtn = html`&lt;button type="button" class="filter-allnone-btn"&gt;None&lt;/button&gt;`;

  allBtn.addEventListener("click", () =&gt; {
    view.value = allValues.slice();
    view.dispatchEvent(new Event("input", { bubbles: true }));
  });
  noneBtn.addEventListener("click", () =&gt; {
    view.value = [];
    view.dispatchEvent(new Event("input", { bubbles: true }));
  });

  const btnRow = html`&lt;div class="filter-allnone-row"&gt;${allBtn}${noneBtn}&lt;/div&gt;`;
  const wrap = html`&lt;div&gt;${view}${btnRow}&lt;/div&gt;`;
  wrap.value = view.value;
  view.addEventListener("input", () =&gt; {
    wrap.value = view.value;
    wrap.dispatchEvent(new Event("input"));
  });
  return wrap;
}

// custom Observable view: either the checkbox or the study's title toggles
// whether that dataset_id is included in the real filters below
// (klf/trf/hcf), exactly like the Inputs.select this replaces. A separate
// "Study details" button expands an inline preview, accordion-style,
// without changing what's included.
function datasetPicker(datasets, defaultIds) {
  const root = html`&lt;div class="dp-wrap"&gt;&lt;/div&gt;`;
  const included = new Set(defaultIds);
  let expandedId = null;

  const search = html`&lt;input class="dp-search" type="text" placeholder="Filter datasets…"&gt;`;
  const countLabel = html`&lt;span class="dp-count"&gt;&lt;/span&gt;`;
  const list = html`&lt;ul class="dp-list"&gt;&lt;/ul&gt;`;

  function notify() {
    root.value = Array.from(included);
    root.dispatchEvent(new Event("input", { bubbles: true }));
  }

  // "All"/"None" always apply to the full dataset list, not just whatever
  // the search box currently narrows the visible rows down to
  const allBtn = html`&lt;button type="button" class="filter-allnone-btn"&gt;All&lt;/button&gt;`;
  const noneBtn = html`&lt;button type="button" class="filter-allnone-btn"&gt;None&lt;/button&gt;`;
  allBtn.addEventListener("click", () =&gt; {
    for (const d of datasets) included.add(d.id);
    render();
    notify();
  });
  noneBtn.addEventListener("click", () =&gt; {
    included.clear();
    render();
    notify();
  });
  const btnRow = html`&lt;div class="filter-allnone-row"&gt;${allBtn}${noneBtn}&lt;/div&gt;`;

  function render() {
    const q = search.value.trim().toLowerCase();
    const filtered = datasets.filter(d =&gt; {
      if (!q) return true;
      const hay = [d.title, d.id, ...d.languages, ...d.countries].join(" ").toLowerCase();
      return hay.includes(q);
    });

    countLabel.textContent = `${included.size} of ${datasets.length} included`;
    list.replaceChildren();

    for (const d of filtered) {
      const li = html`&lt;li class="dp-item"&gt;&lt;/li&gt;`;

      const cb = html`&lt;input type="checkbox"&gt;`;
      cb.checked = included.has(d.id);
      cb.ariaLabel = `Include ${d.title}`;

      function setIncluded(isIncluded) {
        cb.checked = isIncluded;
        if (isIncluded) included.add(d.id); else included.delete(d.id);
        countLabel.textContent = `${included.size} of ${datasets.length} included`;
        notify();
      }

      cb.addEventListener("change", () =&gt; setIncluded(cb.checked));

      const titleBtn = html`&lt;button type="button" class="dp-row-title-btn"&gt;
        &lt;span class="dp-row-title"&gt;${d.title}&lt;/span&gt;
        &lt;span class="dp-row-sub"&gt;${d.id} · n=${d.n}&lt;/span&gt;
      &lt;/button&gt;`;
      titleBtn.addEventListener("click", () =&gt; setIncluded(!cb.checked));

      const microBar = dp_klBar(d, 6);
      microBar.className = "dp-microbar dp-kl-bar";

      const detailsBtn = html`&lt;button type="button" class="dp-details-btn"&gt;${expandedId === d.id ? "Hide" : "Details"}&lt;/button&gt;`;
      detailsBtn.setAttribute("aria-expanded", expandedId === d.id);
      detailsBtn.addEventListener("click", () =&gt; {
        expandedId = expandedId === d.id ? null : d.id;
        render();
      });

      const row = html`&lt;div class="dp-row"&gt;&lt;/div&gt;`;
      row.append(cb, titleBtn, microBar, detailsBtn);

      li.append(row);
      if (expandedId === d.id) li.append(dp_expandContent(d));

      list.append(li);
    }
  }

  search.addEventListener("input", render);
  root.append(search, btnRow, countLabel, list);
  render();

  root.value = Array.from(included);
  return root;
}






































